<script setup lang="ts">
import {onMounted,ref} from 'vue';import {apiFetch} from '../api';
type AdminLine={id:string;shortName:string;name:string;color:string;version:number};type ImportTask={id:string;filename:string;status:string;errors:Array<{row:number;message:string}>;version:number};
const lines=ref<AdminLine[]>([]),tasks=ref<ImportTask[]>([]),messaging=ref<{importQueue:number;deadLetterQueue:number}|null>(null),error=ref(''),message=ref(''),file=ref<File|null>(null),busy=ref(false),loaded=ref(false);
async function refresh(){error.value='';message.value='';try{const [lineResponse,taskResponse,messageResponse]=await Promise.all([apiFetch('/api/admin/transit/lines'),apiFetch('/api/admin/operations/imports'),apiFetch('/api/admin/operations/messaging')]);lines.value=await lineResponse.json();tasks.value=await taskResponse.json();messaging.value=await messageResponse.json()}catch(e){error.value=e instanceof Error?e.message:'Não foi possível carregar a administração.'}finally{loaded.value=true}}
async function save(line:AdminLine){busy.value=true;error.value='';message.value='';try{const updated=await (await apiFetch(`/api/admin/transit/lines/${line.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:line.name,color:line.color,version:line.version})})).json();Object.assign(line,updated);message.value='Linha atualizada; a operação foi auditada.'}catch(e){error.value=e instanceof Error?e.message:'Não foi possível salvar.'}finally{busy.value=false}}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null}
async function upload(){if(!file.value)return;busy.value=true;try{const form=new FormData();form.append('file',file.value);await apiFetch('/api/admin/operations/imports',{method:'POST',body:form});message.value='Arquivo recebido. Atualize o painel para acompanhar validação assíncrona.';await refresh()}catch(e){error.value=e instanceof Error?e.message:'Falha no upload.'}finally{busy.value=false}}
async function publish(task:ImportTask){busy.value=true;error.value='';message.value='';try{await apiFetch(`/api/admin/operations/imports/${task.id}/publish?version=${task.version}`,{method:'POST'});await refresh();message.value='Catálogo publicado atomicamente.'}catch(e){error.value=e instanceof Error?e.message:'Falha na publicação.'}finally{busy.value=false}}
async function reprocess(task:ImportTask){busy.value=true;error.value='';message.value='';try{await apiFetch(`/api/admin/operations/imports/${task.id}/reprocess`,{method:'POST'});await refresh();message.value='Nova tentativa registrada e auditada.'}catch(e){error.value=e instanceof Error?e.message:'Falha no reprocessamento.'}finally{busy.value=false}}
onMounted(refresh)
</script>
<template><section id="admin" class="workspace-panel admin-panel" aria-labelledby="admin-title"><header><div><h2 id="admin-title">Operação demonstrativa</h2><p>Alterações exigem papel ADMIN, CSRF e versão atual. Importações só publicam depois de validadas.</p></div><button class="secondary" :disabled="busy" @click="refresh">Atualizar estados</button></header><p v-if="message" class="success-message" role="status">{{ message }}</p><p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="!loaded" role="status">Carregando operação…</p><div v-if="messaging" class="queue-status"><span>Fila de importação <strong>{{ messaging.importQueue }}</strong></span><span>DLQ <strong>{{ messaging.deadLetterQueue }}</strong></span></div><div v-if="loaded" class="admin-grid"><div><h3>Catálogo de linhas</h3><p v-if="!lines.length" class="empty-copy">Nenhuma linha publicada.</p><ul class="editable-lines"><li v-for="line in lines" :key="line.id"><strong>{{ line.shortName }}</strong><label :for="`name-${line.id}`">Nome</label><input :id="`name-${line.id}`" v-model="line.name"><label :for="`color-${line.id}`">Cor hexadecimal</label><input :id="`color-${line.id}`" v-model="line.color" pattern="#[0-9A-Fa-f]{6}"><button class="secondary" :disabled="busy" @click="save(line)">Salvar versão {{ line.version }}</button></li></ul></div><div><h3>Importar CSV</h3><p class="help-copy">Cabeçalho: type,id,name,latitude,longitude,short_name,color,provenance. A primeira versão aceita STOP e LINE.</p><label for="catalog-file">Arquivo CSV</label><input id="catalog-file" type="file" accept=".csv,text/csv" @change="choose"><button class="primary" :disabled="!file||busy" @click="upload">{{ busy?'Processando…':'Validar de forma assíncrona' }}</button><p v-if="!tasks.length" class="empty-copy">Nenhuma importação enviada.</p><ul class="plain-list task-list"><li v-for="task in tasks" :key="task.id"><span><strong>{{ task.filename }}</strong><small>{{ task.status }} · versão {{ task.version }}</small><small v-for="issue in task.errors" :key="issue.row">Linha {{ issue.row }}: {{ issue.message }}</small></span><button v-if="task.status==='READY'" class="text-action" :disabled="busy" @click="publish(task)">Publicar</button><button v-if="task.status==='FAILED'" class="text-action" :disabled="busy" @click="reprocess(task)">Reprocessar</button></li></ul></div></div></section></template>
